script:
// Reemplaza el "+ Nuevo" estandar de Cita de Taller por un wizard de 2 pasos
// fiel al flujo real de GeneXus (CitasExww -> Citassd). Ver bitacora
// migracion-erpnext/citas.md, seccion "Flujo real de alta/agendamiento de
// una Cita" (reescrita 2026-10-01) para el detalle linea por linea de cada
// control replicado.
//
// v2 (2026-10-01): agrega buscador por PLACA + ficha completa de referencia
// (Paso 1: dueno, descripcion del vehiculo, telefonos disponibles, email,
// direccion, cedula/RUC, citas pendientes); widget de cupos en tiempo real +
// selector de Bahia + "Dos espacios"/"Tiempo aproximado" (Paso 2).
//
// v3 (2026-10-12): correcciones de la seccion "Modelo de datos" #12.D
// (re-verificacion directa del wizard real contra la KB viva, con hallazgos
// nuevos no vistos en el snapshot del 2026-10-01):
// - Buscador de 3 campos reales (Placa/Chasis, Cliente, RUC/Cedula - antes
//   solo Placa), igual a `CitasExww` (&GenericFilter_Grid/&fDgCxcNombre/
//   &fDgCxcRuc).
// - Boton "Crear sin buscar": abre el formulario estandar de Frappe en blanco
//   (bypass total del wizard) para cuando el buscador no encuentra el
//   vehiculo/cliente.
// - Bloqueo real "cliente inactivo" (antes ausente): si el Customer dueno del
//   vehiculo esta `disabled`, se bloquea la seleccion con el mismo mensaje
//   exacto que usa GeneXus (`Event 'Seleccionar'` de CitasExww).
// - El chequeo de cupo pasa de "advertencia, se puede continuar igual" a
//   BLOQUEO real salvo que el usuario tilde "Cita Adicional" - replica
//   `Sub 'U_Confirmar'` de Citassd (`&HayDisponibilidad=true OR
//   &CTAdicional.Trim()<>''`, la unica forma real de agendar sobre un cupo
//   lleno).
//
// Fuera de alcance explicito en esta version (ver citas.md):
// - "Proximo mantenimiento": depende de un REST externo no migrado
//   (getRest_consultamantenimiento) - no se muestra ningun campo para esto.
// - "Sobrecupo" (boton gateado por permiso) / "Cita especial" (variante de
//   Adicional gateada por permiso): confirmados en la KB el 2026-10-12, pero
//   ambos dependen de un permiso puntual de GeneXus (`UserActivityType`) sin
//   equivalente migrado a un Rol de Frappe todavia - quedan fuera de esta
//   pasada, el campo base `cita_adicional` sigue cubriendo el caso general.
if (!window.__bahia_cita_wizard_installed) {
	window.__bahia_cita_wizard_installed = true;

	// En `window` (no `const` de bloque) a proposito: el boton "+ Crear sin
	// buscar" de mas abajo (fuera de este bloque) necesita poder llamar al
	// `new_doc` original sin pasar de nuevo por el wizard.
	window.__bahia_original_new_doc = frappe.new_doc;
	frappe.new_doc = function (doctype, opts, init_callback) {
		if (doctype === "Cita de Taller") {
			bahia_show_cita_wizard();
			return Promise.resolve();
		}
		return window.__bahia_original_new_doc.apply(this, arguments);
	};
}

const BAHIA_CUPO_BUCKET_LABELS = {
	taller: "Mant. / Taller",
	movil: "Movil",
	express_adicional: "Express Adicional",
	taller_adicional: "Taller Adicional",
};

function bahia_show_cita_wizard() {
	let ciacod_actual = null;
	let cupos_actuales = null;

	const set_state = (data) => {
		ciacod_actual = (data && data.ciacod) || null;
	};

	let dialog;
	dialog = new frappe.ui.Dialog({
		title: __("Nueva Cita de Taller"),
		size: "extra-large",
		fields: [
			{
				fieldtype: "Section Break",
				label: __("Paso 1 - Buscar Vehiculo/Cliente"),
			},
			{
				fieldtype: "Data",
				fieldname: "placa_busqueda",
				label: __("Placa / Chasis"),
				description: __("Placa exacta o inicio del chasis (VIN)"),
			},
			{ fieldtype: "Column Break" },
			{
				fieldtype: "Data",
				fieldname: "cliente_busqueda",
				label: __("Cliente"),
				description: __("Nombre del cliente (busca por 'contiene')"),
			},
			{ fieldtype: "Column Break" },
			{
				fieldtype: "Data",
				fieldname: "ruc_busqueda",
				label: __("RUC / Cedula"),
				description: __("Busca por inicio del RUC/Cedula"),
			},
			{ fieldtype: "Section Break" },
			{
				fieldtype: "Button",
				fieldname: "buscar_placa_btn",
				label: __("Buscar"),
				click: () => bahia_buscar_por_placa(dialog, set_state),
			},
			{ fieldtype: "Column Break" },
			{
				fieldtype: "Button",
				fieldname: "crear_sin_buscar_btn",
				label: __("+ Crear sin buscar"),
				description: __("Abre el formulario estandar en blanco (sin usar este buscador)"),
				click: () => {
					dialog.hide();
					window.__bahia_original_new_doc.call(frappe, "Cita de Taller");
				},
			},
			{ fieldtype: "Section Break" },
			{ fieldtype: "HTML", fieldname: "resultados_busqueda" },
			{ fieldtype: "HTML", fieldname: "ficha_vehiculo" },
			{
				fieldtype: "Link",
				fieldname: "vehiculo",
				label: __("...o por codigo interno de Vehiculo (avanzado)"),
				options: "Vehiculo",
				onchange: () => bahia_cargar_vehiculo_directo(dialog, set_state),
			},

			{
				fieldtype: "Section Break",
				label: __("Paso 2 - Datos de la Cita"),
				depends_on: "eval:doc.vehiculo",
			},
			{
				fieldtype: "Select",
				fieldname: "origen_canal_cita",
				label: __("Tipo"),
				options: [
					"Mant. Plus (P)",
					"Movil (M)",
					"Mantenimiento (E)",
					"Diagnostico (D)",
					"Reparacion (T)",
				].join("\n"),
				default: "Mantenimiento (E)",
				reqd: 1,
				depends_on: "eval:doc.vehiculo",
				onchange: () => bahia_refrescar_cupos(dialog, (c) => (cupos_actuales = c)),
			},
			{
				fieldtype: "Link",
				fieldname: "sucursal",
				label: __("Sucursal"),
				options: "Branch",
				reqd: 1,
				depends_on: "eval:doc.vehiculo",
				get_query: () => (ciacod_actual ? { filters: { ciacod: ciacod_actual } } : {}),
				onchange: () => {
					dialog.set_value("bahia", "");
					bahia_refrescar_cupos(dialog, (c) => (cupos_actuales = c));
				},
			},
			{
				fieldtype: "Link",
				fieldname: "bahia",
				label: __("Bahia"),
				options: "Bahia de Sucursal",
				depends_on: "eval:doc.vehiculo",
				description: __("Filtrada por la Sucursal elegida"),
				get_query: () => {
					const suc = dialog.get_value("sucursal");
					return suc ? { filters: { sucursal: suc } } : {};
				},
			},
			{ fieldtype: "Column Break", depends_on: "eval:doc.vehiculo" },
			{
				fieldtype: "Date",
				fieldname: "fecha_cita",
				label: __("Fecha"),
				reqd: 1,
				depends_on: "eval:doc.vehiculo",
				onchange: () => bahia_refrescar_cupos(dialog, (c) => (cupos_actuales = c)),
			},
			{
				fieldtype: "Time",
				fieldname: "hora_cita",
				label: __("Hora"),
				reqd: 1,
				depends_on: "eval:doc.vehiculo",
			},
			{
				fieldtype: "Select",
				fieldname: "turno",
				label: __("Turno"),
				options: "Diurno\nNocturno",
				default: "Diurno",
				depends_on: "eval:doc.vehiculo",
			},

			{
				fieldtype: "Section Break",
				label: __("Cupos"),
				depends_on: "eval:doc.vehiculo",
			},
			{ fieldtype: "HTML", fieldname: "cupos_widget" },
			{
				fieldtype: "Check",
				fieldname: "cita_adicional",
				label: __("Cita Adicional"),
				description: __("Ocupa un cupo del bucket 'Adicional' en vez del cupo base - ver widget de arriba"),
				depends_on: "eval:doc.vehiculo",
				onchange: () => bahia_refrescar_cupos(dialog, (c) => (cupos_actuales = c)),
			},
			{ fieldtype: "Column Break", depends_on: "eval:doc.vehiculo" },
			{
				fieldtype: "Check",
				fieldname: "dos_espacios",
				label: __("Dos espacios"),
				description: __(
					"Valor estimado/manual - en GeneXus es un indicador automatico " +
						"(Citas016/HorasPorMantenimiento, solo canal Express) cuya tabla de " +
						"configuracion todavia no esta migrada."
				),
				depends_on: "eval:doc.vehiculo",
			},
			{
				fieldtype: "Float",
				fieldname: "tiempo_aproximado_horas",
				label: __("Tiempo aproximado (horas)"),
				description: __(
					"Valor estimado/manual - en GeneXus se calcula sumando FLAT_RATE001 " +
						"por cada trabajo elegido, logica todavia no migrada."
				),
				depends_on: "eval:doc.vehiculo",
			},

			{ fieldtype: "Section Break", depends_on: "eval:doc.vehiculo" },
			{
				fieldtype: "Link",
				fieldname: "cliente",
				label: __("Cliente"),
				options: "Customer",
				description: __("Resuelto automaticamente desde el vehiculo - editable si no coincide."),
				depends_on: "eval:doc.vehiculo",
			},
			{
				fieldtype: "Check",
				fieldname: "confirmacion",
				label: __("Confirmacion"),
				depends_on: "eval:doc.vehiculo",
			},
			{ fieldtype: "Column Break", depends_on: "eval:doc.vehiculo" },
			{
				fieldtype: "Small Text",
				fieldname: "observaciones_cliente",
				label: __("Observaciones"),
				depends_on: "eval:doc.vehiculo",
			},

			{
				fieldtype: "Section Break",
				label: __("Servicios Solicitados"),
				depends_on: "eval:doc.vehiculo",
			},
			{
				fieldtype: "Table",
				fieldname: "servicios_solicitados",
				label: __("Servicios Solicitados"),
				options: "Cita Taller Servicio",
				fields: [
					{
						fieldtype: "Link",
						fieldname: "tipo_trabajo",
						options: "Item",
						label: __("Tipo de Trabajo"),
						in_list_view: 1,
					},
					{
						fieldtype: "Currency",
						fieldname: "precio",
						label: __("Precio"),
						in_list_view: 1,
					},
				],
				depends_on: "eval:doc.vehiculo",
			},
		],
		primary_action_label: __("Crear Cita"),
		primary_action: (values) => bahia_confirm_cita_wizard(dialog, values, () => cupos_actuales),
	});

	dialog.show();

	["placa_busqueda", "cliente_busqueda", "ruc_busqueda"].forEach((fieldname) => {
		const field = dialog.fields_dict[fieldname];
		if (field && field.$input) {
			field.$input.on("keydown", (e) => {
				if (e.which === 13) {
					e.preventDefault();
					bahia_buscar_por_placa(dialog, set_state);
				}
			});
		}
	});
}

async function bahia_buscar_por_placa(dialog, set_state) {
	const placa = (dialog.get_value("placa_busqueda") || "").trim();
	const cliente_nombre = (dialog.get_value("cliente_busqueda") || "").trim();
	const ruc = (dialog.get_value("ruc_busqueda") || "").trim();
	if (!placa && !cliente_nombre && !ruc) {
		frappe.show_alert({
			message: __("Ingrese Placa/Chasis, Cliente o RUC/Cedula"),
			indicator: "orange",
		});
		return;
	}
	dialog.set_df_property(
		"resultados_busqueda",
		"options",
		`<div class="text-muted">${__("Buscando...")}</div>`
	);
	dialog.set_df_property("ficha_vehiculo", "options", "");

	const r = await frappe.call({
		method: "bahia_theme.api.buscar_vehiculo_placa",
		args: { placa, cliente_nombre, ruc },
	});
	const resultados = (r && r.message) || [];

	if (!resultados.length) {
		dialog.set_df_property(
			"resultados_busqueda",
			"options",
			`<div class="alert alert-warning" style="padding:6px 10px;">${__(
				"No se encontraron vehiculos vendidos que coincidan con esa busqueda"
			)}</div>`
		);
		dialog.set_value("vehiculo", "");
		return;
	}

	if (resultados.length === 1) {
		dialog.set_df_property("resultados_busqueda", "options", "");
		bahia_seleccionar_vehiculo(dialog, set_state, resultados[0]);
		return;
	}

	window.__bahia_cita_resultados = resultados;
	const html =
		`<div class="list-group">` +
		resultados
			.map(
				(v, idx) =>
					`<a href="#" class="list-group-item bahia-cita-resultado" data-idx="${idx}" style="display:block;padding:8px 12px;">
						<b>${frappe.utils.escape_html(v.placa || "")}</b> - ${frappe.utils.escape_html(
						v.descripcion || v.modelo || ""
					)}
						&nbsp;<span class="text-muted">(${frappe.utils.escape_html(v.company || "")})</span>
					</a>`
			)
			.join("") +
		`</div>`;
	dialog.set_df_property("resultados_busqueda", "options", html);
	dialog.$wrapper
		.find("a.bahia-cita-resultado")
		.off("click")
		.on("click", function (e) {
			e.preventDefault();
			const idx = $(this).data("idx");
			bahia_seleccionar_vehiculo(dialog, set_state, window.__bahia_cita_resultados[idx]);
		});
}

async function bahia_cargar_vehiculo_directo(dialog, set_state) {
	const vehiculo = dialog.get_value("vehiculo");
	if (!vehiculo) {
		dialog.set_df_property("ficha_vehiculo", "options", "");
		return;
	}
	const r = await frappe.call({
		method: "bahia_theme.api.ficha_vehiculo",
		args: { vehiculo },
	});
	if (r && r.message) {
		dialog.set_df_property("resultados_busqueda", "options", "");
		bahia_seleccionar_vehiculo(dialog, set_state, r.message, { skip_vehiculo_set: true });
	}
}

function bahia_seleccionar_vehiculo(dialog, set_state, data, opts) {
	opts = opts || {};
	dialog.set_df_property("resultados_busqueda", "options", "");

	if (data.cliente_disabled) {
		// Replica el bloqueo real de GeneXus (Event 'Seleccionar' de
		// CitasExww, ver citas.md seccion 12.A) - mismo mensaje exacto. No se
		// setea "vehiculo" para que el Paso 2 (depends_on: doc.vehiculo) no
		// se abra.
		dialog.set_value("vehiculo", "");
		dialog.set_value("cliente", "");
		dialog.set_df_property(
			"ficha_vehiculo",
			"options",
			`<div class="alert alert-danger" style="padding:8px 12px;">${__(
				"No se permite crear citas para autos asociados a clientes inactivos."
			)}</div>`
		);
		return;
	}

	if (!opts.skip_vehiculo_set) {
		dialog.set_value("vehiculo", data.vehiculo);
	}
	dialog.set_value("cliente", data.cliente || "");
	set_state(data);
	bahia_render_ficha(dialog, data);
}

function bahia_render_ficha(dialog, data) {
	const telefonosHtml =
		(data.telefonos || [])
			.map((t) => `<div><b>${frappe.utils.escape_html(t.label)}:</b> ${frappe.utils.escape_html(t.valor)}</div>`)
			.join("") || `<div class="text-muted">${__("Sin telefonos registrados")}</div>`;

	let pendientesHtml = "";
	if (data.citas_pendientes && data.citas_pendientes.length) {
		pendientesHtml = `<div class="alert alert-warning" style="margin-top:8px; padding:6px 10px;">
			<b>${__("Este vehiculo ya tiene cita(s) pendiente(s)")}:</b>
			<ul style="margin-bottom:0;">
				${data.citas_pendientes
					.map(
						(c) =>
							`<li>${frappe.utils.escape_html(c.name)} - ${
								frappe.datetime.str_to_user(c.fecha_cita) || ""
							} ${c.hora_cita || ""} (${frappe.utils.escape_html(c.estado || "")}, ${frappe.utils.escape_html(
								c.origen_canal_cita || ""
							)})</li>`
					)
					.join("")}
			</ul>
		</div>`;
	}

	const html = `
		<div class="bahia-ficha-vehiculo" style="border:1px solid var(--border-color); border-radius:6px; padding:10px 14px; margin-top:4px;">
			<div style="display:flex; justify-content:space-between; flex-wrap:wrap;">
				<div>
					<div style="font-size:15px; font-weight:600;">${frappe.utils.escape_html(data.descripcion || data.modelo || "-")}</div>
					<div class="text-muted">${__("Placa")}: <b>${frappe.utils.escape_html(data.placa || "-")}</b>
						&nbsp;|&nbsp; ${__("Color")}: ${frappe.utils.escape_html(data.color || "-")}
						&nbsp;|&nbsp; ${__("Anio")}: ${frappe.utils.escape_html(data.anio != null ? String(data.anio) : "-")}
						&nbsp;|&nbsp; VIN: ${frappe.utils.escape_html(data.vin || "-")}
					</div>
				</div>
				<div class="text-muted">${__("Estado comercial")}: ${frappe.utils.escape_html(data.estado_comercial || "-")}</div>
			</div>
			<hr style="margin:8px 0;">
			<div style="display:flex; gap:24px; flex-wrap:wrap;">
				<div>
					<div><b>${__("Dueno")}:</b> ${frappe.utils.escape_html(data.cliente_nombre || __("No encontrado - seleccione Cliente manualmente abajo"))}</div>
					${
						data.cliente_ruc
							? `<div><b>${__("Cedula/RUC")}:</b> ${frappe.utils.escape_html(data.cliente_ruc)}</div>`
							: ""
					}
					<div><b>${__("Email")}:</b> ${frappe.utils.escape_html(data.cliente_email || "-")}</div>
					<div><b>${__("Direccion")}:</b> ${frappe.utils.escape_html(data.cliente_direccion || "-")}</div>
				</div>
				<div>${telefonosHtml}</div>
			</div>
			${pendientesHtml}
		</div>`;
	dialog.set_df_property("ficha_vehiculo", "options", html);
}

async function bahia_refrescar_cupos(dialog, set_cupos) {
	const sucursal = dialog.get_value("sucursal");
	const fecha = dialog.get_value("fecha_cita");
	if (!sucursal || !fecha) {
		dialog.set_df_property("cupos_widget", "options", "");
		set_cupos(null);
		return;
	}
	dialog.set_df_property(
		"cupos_widget",
		"options",
		`<div class="text-muted">${__("Consultando cupos...")}</div>`
	);
	const r = await frappe.call({
		method: "bahia_theme.api.cupos_disponibles",
		args: { sucursal, fecha },
	});
	const data = (r && r.message) || {};
	set_cupos(data);

	if (data.sin_configuracion) {
		dialog.set_df_property(
			"cupos_widget",
			"options",
			`<div class="alert alert-secondary" style="padding:6px 10px;">${__(
				"Esta sucursal no tiene configuracion de cupos cargada"
			)}</div>`
		);
		return;
	}
	if (!data.buckets) {
		dialog.set_df_property("cupos_widget", "options", "");
		return;
	}

	let aviso = "";
	if (data.es_domingo) {
		aviso = `<div class="text-muted" style="margin-bottom:4px;">${__(
			"Domingo: sin cupos configurados (regla fija de GeneXus)"
		)}</div>`;
	}

	const filas = Object.keys(data.buckets)
		.map((b) => {
			const info = data.buckets[b];
			const color = info.disponibles > 0 ? "text-success" : "text-danger";
			return `<td style="padding:4px 10px; text-align:center;">
				<div style="font-size:11px; color:#888;">${BAHIA_CUPO_BUCKET_LABELS[b]}</div>
				<div class="${color}" style="font-weight:600;">${info.disponibles} / ${info.configurado}</div>
				<div style="font-size:10px; color:#aaa;">${__("usados")}: ${info.usados}</div>
			</td>`;
		})
		.join("");

	dialog.set_df_property(
		"cupos_widget",
		"options",
		`${aviso}<table style="width:100%;"><tr>${filas}</tr></table>
		<div style="font-size:11px; color:#888; margin-top:4px;">${__(
			"Disponibles / Configurados para la fecha elegida. En 0, hay que marcar 'Cita Adicional' para poder guardar."
		)}</div>`
	);
}

function bahia_bucket_para(origen, adicional) {
	if (!origen) return null;
	if (origen.indexOf("Reparacion") === 0) return adicional ? "taller_adicional" : "taller";
	if (origen.indexOf("Movil") === 0) return "movil";
	if (adicional) return "express_adicional";
	return null;
}

function bahia_confirm_cita_wizard(dialog, values, get_cupos) {
	if (!values.vehiculo) {
		frappe.msgprint(__("Seleccione un vehiculo"));
		return;
	}
	if (!values.origen_canal_cita || !values.sucursal || !values.fecha_cita || !values.hora_cita) {
		frappe.msgprint(__("Complete Tipo, Sucursal, Fecha y Hora"));
		return;
	}

	const bucket = bahia_bucket_para(values.origen_canal_cita, !!values.cita_adicional);
	const cupos = get_cupos();
	if (
		bucket &&
		cupos &&
		cupos.buckets &&
		cupos.buckets[bucket] &&
		cupos.buckets[bucket].disponibles <= 0 &&
		!values.cita_adicional
	) {
		// Bloqueo real (replica Sub 'U_Confirmar' de Citassd: el guardado solo
		// se arma si HayDisponibilidad=true O CTAdicional<>'' - la unica forma
		// real de agendar sobre un cupo lleno es marcar "Cita Adicional").
		const info = cupos.buckets[bucket];
		frappe.msgprint({
			title: __("Sin cupo disponible"),
			indicator: "red",
			message: __(
				"No hay cupo disponible para '{0}' en la fecha elegida ({1} usados de {2} configurados). Marque 'Cita Adicional' para agendar igual.",
				[BAHIA_CUPO_BUCKET_LABELS[bucket], info.usados, info.configurado]
			),
		});
		return;
	}
	bahia_enviar_cita(dialog, values);
}

function bahia_enviar_cita(dialog, values) {
	dialog.set_primary_action(__("Creando..."), null);

	frappe.call({
		method: "bahia_theme.api.crear_cita_taller",
		args: {
			vehiculo: values.vehiculo,
			origen_canal_cita: values.origen_canal_cita,
			sucursal: values.sucursal,
			bahia: values.bahia,
			fecha_cita: values.fecha_cita,
			hora_cita: values.hora_cita,
			turno: values.turno,
			confirmacion: values.confirmacion,
			cita_adicional: values.cita_adicional,
			dos_espacios: values.dos_espacios,
			tiempo_aproximado_horas: values.tiempo_aproximado_horas,
			observaciones_cliente: values.observaciones_cliente,
			cliente: values.cliente,
			servicios: values.servicios_solicitados,
		},
		freeze: true,
		freeze_message: __("Creando cita..."),
	})
		.then((r) => {
			if (r.message) {
				dialog.hide();
				frappe.show_alert({ message: __("Cita creada: {0}", [r.message]), indicator: "green" });
				frappe.set_route("Form", "Cita de Taller", r.message);
			}
		})
		.finally(() => {
			dialog.set_primary_action(__("Crear Cita"), () =>
				bahia_confirm_cita_wizard(dialog, dialog.get_values(true), () => null)
			);
		});
}
